docutils.utils.__init__.uniq:
def uniq(L: list) -> list:
    r = []
    for item in L:
        if item not in r:
            r.append(item)
    return r

docutils.writers.latex2e.__init__._read_:
def _read_block(fp):
    block = [next(fp)]
    for line in fp:
        if not line.strip():
            break
        block.append(line)
    return ''.join(block).rstrip()

docutils.parsers.rst.roles.unimplemented:
def unimplemented_role(role, rawtext, text, lineno, inliner, options=None, content=None):
    msg = inliner.reporter.error('Interpreted text role "%s" not implemented.' % role, line=lineno)
    prb = inliner.problematic(rawtext, rawtext, msg)
    return ([prb], [msg])

